CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateAIAction"(
    p_id UUID DEFAULT NULL,
    p_name varchar(50) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_defaultprompt_clear boolean DEFAULT false,
    p_defaultprompt TEXT DEFAULT NULL,
    p_defaultmodelid_clear boolean DEFAULT false,
    p_defaultmodelid UUID DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwAIActions" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."AIAction"
        (
            "ID",
            "Name",
                "Description",
                "DefaultPrompt",
                "DefaultModelID",
                "IsActive"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_defaultprompt_clear = true THEN NULL ELSE COALESCE(p_defaultprompt, NULL) END,
                CASE WHEN p_defaultmodelid_clear = true THEN NULL ELSE COALESCE(p_defaultmodelid, NULL) END,
                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwAIActions"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
