CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateAIAgentPrompt"(
    p_id UUID DEFAULT NULL,
    p_agentid UUID DEFAULT NULL,
    p_promptid UUID DEFAULT NULL,
    p_purpose_clear boolean DEFAULT false,
    p_purpose TEXT DEFAULT NULL,
    p_executionorder int DEFAULT NULL,
    p_configurationid_clear boolean DEFAULT false,
    p_configurationid UUID DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_contextbehavior varchar(50) DEFAULT NULL,
    p_contextmessagecount_clear boolean DEFAULT false,
    p_contextmessagecount int DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwAIAgentPrompts" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."AIAgentPrompt"
        (
            "ID",
            "AgentID",
                "PromptID",
                "Purpose",
                "ExecutionOrder",
                "ConfigurationID",
                "Status",
                "ContextBehavior",
                "ContextMessageCount"
        )
    VALUES
        (
            v_new_id,
            p_agentid,
                p_promptid,
                CASE WHEN p_purpose_clear = true THEN NULL ELSE COALESCE(p_purpose, NULL) END,
                COALESCE(p_executionorder, 0),
                CASE WHEN p_configurationid_clear = true THEN NULL ELSE COALESCE(p_configurationid, NULL) END,
                COALESCE(p_status, 'Active'),
                COALESCE(p_contextbehavior, 'Complete'),
                CASE WHEN p_contextmessagecount_clear = true THEN NULL ELSE COALESCE(p_contextmessagecount, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwAIAgentPrompts"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
