CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spUpdateArtifact"(
    p_id UUID,
    p_environmentid UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_typeid UUID DEFAULT NULL,
    p_comments_clear boolean DEFAULT false,
    p_comments TEXT DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_visibility varchar(20) DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwArtifacts" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE ${flyway:defaultSchema}."Artifact"
    SET
        "EnvironmentID" = COALESCE(p_environmentid, "EnvironmentID"),
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "TypeID" = COALESCE(p_typeid, "TypeID"),
        "Comments" = CASE WHEN p_comments_clear = true THEN NULL ELSE COALESCE(p_comments, "Comments") END,
        "UserID" = COALESCE(p_userid, "UserID"),
        "Visibility" = COALESCE(p_visibility, "Visibility")
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwArtifacts"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
