CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateClusterAnalysisCluster"(
    p_id UUID DEFAULT NULL,
    p_clusteranalysisid UUID DEFAULT NULL,
    p_clusterindex int DEFAULT NULL,
    p_label_clear boolean DEFAULT false,
    p_label varchar(255) DEFAULT NULL,
    p_membercount int DEFAULT NULL,
    p_color_clear boolean DEFAULT false,
    p_color varchar(20) DEFAULT NULL,
    p_isuseredited BOOLEAN DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwClusterAnalysisClusters" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."ClusterAnalysisCluster"
        (
            "ID",
            "ClusterAnalysisID",
                "ClusterIndex",
                "Label",
                "MemberCount",
                "Color",
                "IsUserEdited"
        )
    VALUES
        (
            v_new_id,
            p_clusteranalysisid,
                p_clusterindex,
                CASE WHEN p_label_clear = true THEN NULL ELSE COALESCE(p_label, NULL) END,
                COALESCE(p_membercount, 0),
                CASE WHEN p_color_clear = true THEN NULL ELSE COALESCE(p_color, NULL) END,
                COALESCE(p_isuseredited, FALSE)
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwClusterAnalysisClusters"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
