    p_communicationrunid UUID DEFAULT NULL,
    p_direction varchar(20) DEFAULT NULL,
    p_messagedate TIMESTAMPTZ DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_messagecontent_clear boolean DEFAULT false,
