CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateCompany"(
    p_id UUID DEFAULT NULL,
    p_name varchar(50) DEFAULT NULL,
    p_description varchar(200) DEFAULT NULL,
    p_website_clear boolean DEFAULT false,
    p_website varchar(100) DEFAULT NULL,
    p_logourl_clear boolean DEFAULT false,
    p_logourl varchar(500) DEFAULT NULL,
    p_domain_clear boolean DEFAULT false,
    p_domain varchar(255) DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwCompanies" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."Company"
        (
            "ID",
            "Name",
                "Description",
                "Website",
                "LogoURL",
                "Domain"
        )
    VALUES
        (
            v_new_id,
            p_name,
                p_description,
                CASE WHEN p_website_clear = true THEN NULL ELSE COALESCE(p_website, NULL) END,
                CASE WHEN p_logourl_clear = true THEN NULL ELSE COALESCE(p_logourl, NULL) END,
                CASE WHEN p_domain_clear = true THEN NULL ELSE COALESCE(p_domain, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwCompanies"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
