CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateCredential"(
    p_id UUID DEFAULT NULL,
    p_credentialtypeid UUID DEFAULT NULL,
    p_categoryid_clear boolean DEFAULT false,
    p_categoryid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_values TEXT DEFAULT NULL,
    p_isdefault BOOLEAN DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_expiresat_clear boolean DEFAULT false,
    p_expiresat TIMESTAMPTZ DEFAULT NULL,
    p_lastvalidatedat_clear boolean DEFAULT false,
    p_lastvalidatedat TIMESTAMPTZ DEFAULT NULL,
    p_lastusedat_clear boolean DEFAULT false,
    p_lastusedat TIMESTAMPTZ DEFAULT NULL,
    p_iconclass_clear boolean DEFAULT false,
    p_iconclass varchar(100) DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwCredentials" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."Credential"
        (
            "ID",
            "CredentialTypeID",
                "CategoryID",
                "Name",
                "Description",
                "Values",
                "IsDefault",
                "IsActive",
                "ExpiresAt",
                "LastValidatedAt",
                "LastUsedAt",
                "IconClass"
        )
    VALUES
        (
            v_new_id,
            p_credentialtypeid,
                CASE WHEN p_categoryid_clear = true THEN NULL ELSE COALESCE(p_categoryid, NULL) END,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_values,
                COALESCE(p_isdefault, FALSE),
                COALESCE(p_isactive, TRUE),
                CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, NULL) END,
                CASE WHEN p_lastvalidatedat_clear = true THEN NULL ELSE COALESCE(p_lastvalidatedat, NULL) END,
                CASE WHEN p_lastusedat_clear = true THEN NULL ELSE COALESCE(p_lastusedat, NULL) END,
                CASE WHEN p_iconclass_clear = true THEN NULL ELSE COALESCE(p_iconclass, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwCredentials"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
