CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spUpdateCredential"(
    p_id UUID,
    p_credentialtypeid UUID DEFAULT NULL,
    p_categoryid_clear boolean DEFAULT false,
    p_categoryid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_values TEXT DEFAULT NULL,
    p_isdefault BOOLEAN DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_expiresat_clear boolean DEFAULT false,
    p_expiresat TIMESTAMPTZ DEFAULT NULL,
    p_lastvalidatedat_clear boolean DEFAULT false,
    p_lastvalidatedat TIMESTAMPTZ DEFAULT NULL,
    p_lastusedat_clear boolean DEFAULT false,
    p_lastusedat TIMESTAMPTZ DEFAULT NULL,
    p_iconclass_clear boolean DEFAULT false,
    p_iconclass varchar(100) DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwCredentials" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE ${flyway:defaultSchema}."Credential"
    SET
        "CredentialTypeID" = COALESCE(p_credentialtypeid, "CredentialTypeID"),
        "CategoryID" = CASE WHEN p_categoryid_clear = true THEN NULL ELSE COALESCE(p_categoryid, "CategoryID") END,
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "Values" = COALESCE(p_values, "Values"),
        "IsDefault" = COALESCE(p_isdefault, "IsDefault"),
        "IsActive" = COALESCE(p_isactive, "IsActive"),
        "ExpiresAt" = CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, "ExpiresAt") END,
        "LastValidatedAt" = CASE WHEN p_lastvalidatedat_clear = true THEN NULL ELSE COALESCE(p_lastvalidatedat, "LastValidatedAt") END,
        "LastUsedAt" = CASE WHEN p_lastusedat_clear = true THEN NULL ELSE COALESCE(p_lastusedat, "LastUsedAt") END,
        "IconClass" = CASE WHEN p_iconclass_clear = true THEN NULL ELSE COALESCE(p_iconclass, "IconClass") END
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwCredentials"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
