CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."fn_trg_update_dataset"()
RETURNS TRIGGER AS $$
BEGIN
    NEW."__mj_UpdatedAt" := NOW() AT TIME ZONE 'UTC';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS "trg_update_dataset" ON ${flyway:defaultSchema}."Dataset";

CREATE TRIGGER "trg_update_dataset"
BEFORE UPDATE ON ${flyway:defaultSchema}."Dataset"
FOR EACH ROW
EXECUTE FUNCTION ${flyway:defaultSchema}."fn_trg_update_dataset"();

