    p_recordmetadata_clear boolean DEFAULT false,
    p_recordmetadata TEXT DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwDuplicateRunDetailMatches" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."DuplicateRunDetailMatch"
        (
