) RETURNS SETOF ${flyway:defaultSchema}."vwEncryptionKeys" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."EncryptionKey"
        (
            "ID",
            "Name",
                "Description",
                "EncryptionKeySourceID",
                "EncryptionAlgorithmID",
                "KeyLookupValue",
                "KeyVersion",
                "Marker",
                "IsActive",
                "Status",
                "ActivatedAt",
                "ExpiresAt"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                p_encryptionkeysourceid,
                p_encryptionalgorithmid,
                p_keylookupvalue,
                COALESCE(p_keyversion, '1'),
                COALESCE(p_marker, '$ENC$'),
                COALESCE(p_isactive, TRUE),
                COALESCE(p_status, 'Active'),
                CASE WHEN p_activatedat_clear = true THEN NULL ELSE COALESCE(p_activatedat, NULL) END,
                CASE WHEN p_expiresat_clear = true THEN NULL ELSE COALESCE(p_expiresat, NULL) END
        )
    ;

