CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateExplorerNavigationItem"(
    p_id UUID DEFAULT NULL,
    p_sequence int DEFAULT NULL,
    p_name varchar(100) DEFAULT NULL,
    p_route varchar(255) DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_showinhomescreen BOOLEAN DEFAULT NULL,
    p_showinnavigationdrawer BOOLEAN DEFAULT NULL,
    p_iconcssclass_clear boolean DEFAULT false,
    p_iconcssclass varchar(100) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_comments_clear boolean DEFAULT false,
    p_comments TEXT DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwExplorerNavigationItems" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."ExplorerNavigationItem"
        (
            "ID",
            "Sequence",
                "Name",
                "Route",
                "IsActive",
                "ShowInHomeScreen",
                "ShowInNavigationDrawer",
                "IconCSSClass",
                "Description",
                "Comments"
        )
    VALUES
        (
            v_new_id,
            p_sequence,
                p_name,
                p_route,
                COALESCE(p_isactive, TRUE),
                COALESCE(p_showinhomescreen, FALSE),
                COALESCE(p_showinnavigationdrawer, FALSE),
                CASE WHEN p_iconcssclass_clear = true THEN NULL ELSE COALESCE(p_iconcssclass, NULL) END,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_comments_clear = true THEN NULL ELSE COALESCE(p_comments, NULL) END
