    p_id UUID DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_name varchar(255) DEFAULT NULL,
    p_query varchar(1000) DEFAULT NULL,
    p_filters_clear boolean DEFAULT false,
    p_filters TEXT DEFAULT NULL,
    p_minscore_clear boolean DEFAULT false,
    p_minscore decimal(3, 2) DEFAULT NULL,
    p_maxresults_clear boolean DEFAULT false,
    p_maxresults int DEFAULT NULL,
    p_notifyonnewresults BOOLEAN DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwKnowledgeHubSavedSearches" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."KnowledgeHubSavedSearch"
        (
            "ID",
            "UserID",
                "Name",
                "Query",
                "Filters",
                "MinScore",
                "MaxResults",
                "NotifyOnNewResults"
        )
    VALUES
        (
            v_new_id,
            p_userid,
                p_name,
                p_query,
                CASE WHEN p_filters_clear = true THEN NULL ELSE COALESCE(p_filters, NULL) END,
                CASE WHEN p_minscore_clear = true THEN NULL ELSE COALESCE(p_minscore, NULL) END,
                CASE WHEN p_maxresults_clear = true THEN NULL ELSE COALESCE(p_maxresults, 50) END,
                COALESCE(p_notifyonnewresults, FALSE)
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwKnowledgeHubSavedSearches"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
