) RETURNS SETOF ${flyway:defaultSchema}."vwPermissionDomains" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."PermissionDomain"
        (
            "ID",
            "Name",
                "Description",
                "ProviderClassName",
                "SupportedGranteeTypes",
                "SupportedActions",
