/* Root ID Function SQL for MJ: Projects.ParentID */
-- ============================================================
-- PostgreSQL Generated SQL for Entity: MJ: Projects
-- Item: fnProjectParentID_GetRootID
-- Generated at: 2026-06-19T03:41:00.465Z
-- ============================================================

------------------------------------------------------------
----- ROOT ID FUNCTION FOR: Project.ParentID
------------------------------------------------------------
CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."fn_project_parent_id_get_root_id"(
    p_record_id UUID,
    p_parent_id UUID
) RETURNS UUID AS $$
    WITH RECURSIVE cte_root_parent AS (
        -- Anchor: Start from p_parent_id if not null, otherwise start from p_record_id
        SELECT
            "ID",
            "ParentID",
            "ID" AS root_parent_id,
            0 AS depth
        FROM
            ${flyway:defaultSchema}."Project"
        WHERE
            "ID" = COALESCE(p_parent_id, p_record_id)

        UNION ALL

        -- Recursive: Keep going up the hierarchy
        SELECT
            c."ID",
            c."ParentID",
            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM
            ${flyway:defaultSchema}."Project" c
        INNER JOIN
            cte_root_parent p ON c."ID" = p."ParentID"
        WHERE
            p.depth < 100  -- Prevent infinite loops
    )
    SELECT root_parent_id
    FROM cte_root_parent
    WHERE "ParentID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$$ LANGUAGE sql STABLE;

