) RETURNS SETOF ${flyway:defaultSchema}."vwSearchProviders" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."SearchProvider"
        (
            "ID",
            "Name",
                "Description",
                "DriverClass",
                "Status",
                "Priority",
                "SupportsPreview",
                "MaxResultsOverride",
                "ProviderConfig",
                "CredentialID",
                "DisplayName",
                "Icon",
                "Comments"
        )
    VALUES
        (
            v_new_id,
            p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
