    p_id UUID DEFAULT NULL,
    p_searchscopeid UUID DEFAULT NULL,
    p_searchproviderid UUID DEFAULT NULL,
    p_enabled BOOLEAN DEFAULT NULL,
    p_maxresultsoverride_clear boolean DEFAULT false,
    p_maxresultsoverride int DEFAULT NULL,
    p_providerconfigoverride_clear boolean DEFAULT false,
    p_providerconfigoverride TEXT DEFAULT NULL,
    p_querytransformtemplateid_clear boolean DEFAULT false,
    p_querytransformtemplateid UUID DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwSearchScopeProviders" AS $$
DECLARE
