                "SignatureProviderID",
                "CredentialID",
                "CompanyID",
                "IsActive",
                "IsDefault",
                "DefaultFromName",
                "DefaultFromEmail",
                "Configuration"
        )
    VALUES
        (
            v_new_id,
            p_name,
                p_signatureproviderid,
                p_credentialid,
                CASE WHEN p_companyid_clear = true THEN NULL ELSE COALESCE(p_companyid, NULL) END,
