CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spCreateSignatureProvider"(
    p_id UUID DEFAULT NULL,
    p_name varchar(100) DEFAULT NULL,
    p_serverdriverkey varchar(100) DEFAULT NULL,
    p_isactive BOOLEAN DEFAULT NULL,
    p_priority int DEFAULT NULL,
    p_requiresoauth BOOLEAN DEFAULT NULL,
    p_supportstemplates BOOLEAN DEFAULT NULL,
    p_supportsembeddedsigning BOOLEAN DEFAULT NULL,
    p_configuration_clear boolean DEFAULT false,
    p_configuration TEXT DEFAULT NULL
) RETURNS SETOF ${flyway:defaultSchema}."vwSignatureProviders" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO ${flyway:defaultSchema}."SignatureProvider"
        (
            "ID",
            "Name",
                "ServerDriverKey",
                "IsActive",
                "Priority",
                "RequiresOAuth",
                "SupportsTemplates",
                "SupportsEmbeddedSigning",
                "Configuration"
        )
    VALUES
        (
            v_new_id,
            p_name,
                p_serverdriverkey,
                COALESCE(p_isactive, TRUE),
                COALESCE(p_priority, 0),
                COALESCE(p_requiresoauth, TRUE),
                COALESCE(p_supportstemplates, FALSE),
                COALESCE(p_supportsembeddedsigning, FALSE),
                CASE WHEN p_configuration_clear = true THEN NULL ELSE COALESCE(p_configuration, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwSignatureProviders"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
