                COALESCE(p_isactive, TRUE)
        )
    ;

    RETURN QUERY
    SELECT * FROM ${flyway:defaultSchema}."vwTemplateContents"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
