    p_id UUID DEFAULT NULL,
    p_testrunid UUID DEFAULT NULL,
    p_revieweruserid UUID DEFAULT NULL,
    p_rating_clear boolean DEFAULT false,
    p_rating int DEFAULT NULL,
    p_iscorrect_clear boolean DEFAULT false,
