CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spDeleteAIAgentStep"(
    p_id UUID
) RETURNS TABLE("ID" UUID) AS $$
#variable_conflict use_column
DECLARE
    v_affected_count INTEGER;
    v_rec RECORD;
BEGIN
    -- Cascade: Delete MJ: AI Agent Step Paths records via OriginStepID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."AIAgentStepPath"
        WHERE "OriginStepID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteAIAgentStepPath"(v_rec."ID");
