    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."AIAgentStepPath"
        WHERE "DestinationStepID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteAIAgentStepPath"(v_rec."ID");
    END LOOP;

    
    DELETE FROM ${flyway:defaultSchema}."AIAgentStep"
    WHERE "ID" = p_id;

    GET DIAGNOSTICS v_affected_count = ROW_COUNT;

    IF v_affected_count = 0 THEN
        RETURN QUERY SELECT NULL::UUID AS "ID";
    ELSE
        RETURN QUERY SELECT p_id AS "ID";
    END IF;
END;
