CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."spDeleteReport"(
    p_id UUID
) RETURNS TABLE("ID" UUID) AS $$
#variable_conflict use_column
DECLARE
    v_affected_count INTEGER;
    v_rec RECORD;
BEGIN
    -- Cascade: Delete MJ: Report Snapshots records via ReportID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."ReportSnapshot"
        WHERE "ReportID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteReportSnapshot"(v_rec."ID");
    END LOOP;

        -- Cascade: Delete MJ: Report User States records via ReportID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."ReportUserState"
        WHERE "ReportID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteReportUserState"(v_rec."ID");
    END LOOP;

        -- Cascade: Delete MJ: Report Versions records via ReportID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."ReportVersion"
        WHERE "ReportID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteReportVersion"(v_rec."ID");
    END LOOP;

    
    DELETE FROM ${flyway:defaultSchema}."Report"
    WHERE "ID" = p_id;

    GET DIAGNOSTICS v_affected_count = ROW_COUNT;

    IF v_affected_count = 0 THEN
        RETURN QUERY SELECT NULL::UUID AS "ID";
    ELSE
