        -- Cascade: Delete MJ: Conversation Artifacts records via ConversationID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."ConversationArtifact"
        WHERE "ConversationID" = p_id
    LOOP
