        FROM ${flyway:defaultSchema}."ConversationDetail"
        WHERE "ConversationID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteConversationDetail"(v_rec."ID");
    END LOOP;

        -- Cascade: Set MJ: Reports.ConversationID to NULL
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."Report"
        WHERE "ConversationID" = p_id
    LOOP
