        WHERE "ApplicationID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteApplicationRole"(v_rec."ID");
    END LOOP;

        -- Cascade: Delete MJ: Application Settings records via ApplicationID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."ApplicationSetting"
        WHERE "ApplicationID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteApplicationSetting"(v_rec."ID");
    END LOOP;

        -- Cascade: Set MJ: Conversations.ApplicationID to NULL
