        UPDATE ${flyway:defaultSchema}."Conversation"
        SET "ApplicationID" = NULL
        WHERE "ID" = v_rec."ID";
    END LOOP;

        -- Cascade: Delete MJ: Dashboard User Preferences records via ApplicationID
    FOR v_rec IN
        SELECT "ID"
        FROM ${flyway:defaultSchema}."DashboardUserPreference"
        WHERE "ApplicationID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteDashboardUserPreference"(v_rec."ID");
    END LOOP;

        -- Cascade: Set MJ: Dashboards.ApplicationID to NULL
    FOR v_rec IN
