        WHERE "ApplicationID" = p_id
    LOOP
        PERFORM ${flyway:defaultSchema}."spDeleteUserApplication"(v_rec."ID");
    END LOOP;

    
    DELETE FROM ${flyway:defaultSchema}."Application"
    WHERE "ID" = p_id;

    GET DIAGNOSTICS v_affected_count = ROW_COUNT;

    IF v_affected_count = 0 THEN
        RETURN QUERY SELECT NULL::UUID AS "ID";
